parameters.jsCode:
const item = $input.first();

const url = String(
  item.json.property_url ??
  item.json['Property URL'] ??
  ''
).trim();

const pdf = item.binary?.property_pdf ??
  item.binary?.['Upload Property PDF'];

if (!url && !pdf) {
  throw new Error(
    'Please provide a property URL or upload a PDF.'
  );
}

if (url && pdf) {
  throw new Error(
    'Please use only one input: URL or PDF.'
  );
}

if (url && !/^https?:\/\//i.test(url)) {
  throw new Error('Please enter a valid HTTP(S) URL.');
}

if (pdf && pdf.fileExtension?.toLowerCase() !== 'pdf') {
  throw new Error('Only PDF uploads are supported.');
}

return [{
  json: {
    input_type: pdf ? 'pdf_upload' : 'url',
    property_url: url
  },
  binary: item.binary
}];

// ======================================================
// PREPARE PDF PROPERTY INPUT
// German Property Evaluator - API
// ======================================================

// 1. Read extracted PDF text
const item = $input.first();

const rawText = String(item.json.text || '');

if (!rawText.trim()) {
  throw new Error(
    'No property text extracted from PDF'
  );
}

// 2. Clean extracted text
const cleanedText = rawText
  .replace(/\r/g, '\n')
  .replace(/[ \t]+/g, ' ')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

// 3. Read uploaded file from Webhook
const webhook = $('Webhook').first();

const binary = webhook.binary || {};

const file =
  binary.property_pdf0 ||
  binary.property_pdf ||
  Object.values(binary).find(
    value => value?.mimeType === 'application/pdf'
  );

if (!file) {
  throw new Error(
    'Uploaded PDF not found in Webhook binary data'
  );
}

// 4. Return normalized property data
return [{
  json: {
    property_text: cleanedText,

    source_type: 'pdf',

    source_filename:
      file.fileName || 'unknown.pdf',

    page_count:
      item.json.numpages || null,

    property_url: null,

    input_source: 'api_upload',

    extraction_status: 'completed',

    ready_for_evaluation: true
  }
}];

