parameters.jsCode:
const response = $input.first().json;

// Pinecone response may be wrapped in "body"
const data = response.body || response;
const matches = data.matches || [];

const property = $('Code in JavaScript1').first().json;

const references = matches.map((match, index) => ({
  rank: index + 1,
  similarity: match.score,
  source: match.metadata?.source || 'Unknown',
  file_type: match.metadata?.file_type || 'Unknown',
  text: match.metadata?.text || ''
}));

return [{
  json: {
    property_text: property.property_text,
    property_source: property.source_filename,
    property_url: property.property_url,
    references,
    reference_count: references.length
  }
}];

const response = $input.first().json;
const raw = response.choices?.[0]?.message?.content;

if (!raw || typeof raw !== 'string') {
  throw new Error('Nebius did not return a report.');
}

const cleaned = raw.trim()
  .replace(/^```(?:json)?\s*/i, '')
  .replace(/\s*```$/, '');

let report;
try {
  report = JSON.parse(cleaned);
} catch (error) {
  throw new Error('Invalid Nebius JSON: ' + error.message);
}

const score = Number(report.attractiveness_score);
if (!Number.isInteger(score) || score < 1 || score > 7) {
  throw new Error('Attractiveness score must be 1–7.');
}

const esc = v => String(v ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;')
  .replace(/'/g, '&#39;');

const validNum = v =>
  v !== null && v !== undefined && v !== '' &&
  Number.isFinite(Number(v)) ? Number(v) : null;

const money = v => {
  const n = validNum(v);
  return n === null ? 'Not available' :
    new Intl.NumberFormat('de-DE', {
      style: 'currency',
      currency: 'EUR',
      maximumFractionDigits: 0
    }).format(n);
};

const num = (v, digits = 0) => {
  const n = validNum(v);
  return n === null ? 'Not available' :
    new Intl.NumberFormat('de-DE', {
      maximumFractionDigits: digits
    }).format(n);
};

const price = validNum(report.asking_price);
const area = validNum(report.living_area_sqm);
const rent = validNum(report.monthly_cold_rent);

const priceSqm = price > 0 && area > 0
  ? price / area : null;

const yieldPct = price > 0 && rent !== null && rent >= 0
  ? rent * 12 / price * 100 : null;

const risks = Array.isArray(report.key_risks)
  ? report.key_risks.filter(Boolean).slice(0, 5) : [];

const questions = Array.isArray(report.broker_questions)
  ? report.broker_questions.filter(Boolean).slice(0, 5) : [];

const title = report.property_title || 'Residential Property';
const location = [
  report.neighborhood,
  report.city,
  report.postal_code
].filter(Boolean).join(', ');

const source = $('Code in JavaScript1').first().json;
const sourceName = source.source_filename || 'Uploaded PDF';

const referenceCount =
  $('Code in JavaScript2').first().json.reference_count ?? 0;

const rating = score <= 2
  ? { color: '#b42318', bg: '#fef3f2', label: 'High concern' }
  : score <= 3
  ? { color: '#b45309', bg: '#fffbeb', label: 'Below average' }
  : score === 4
  ? { color: '#64748b', bg: '#f1f5f9', label: 'Neutral' }
  : { color: '#15803d', bg: '#f0fdf4', label: 'Attractive' };

const bars = Array.from({ length: 7 }, (_, i) => `
  <span style="
    flex:1;height:9px;border-radius:4px;
    background:${i < score ? rating.color : '#e2e8f0'};
  "></span>
`).join('');

const metric = (label, value, note = '') => `
  <div style="
    background:#f8fafc;
    border:1px solid #e2e8f0;
    border-radius:12px;
    padding:18px;
    min-width:0;
  ">
    <div style="
      font-size:11px;font-weight:700;
      text-transform:uppercase;
      letter-spacing:1px;color:#64748b;
    ">${esc(label)}</div>
    <div style="
      font-size:23px;font-weight:750;
      color:#0f172a;margin-top:7px;
      overflow-wrap:anywhere;
    ">${esc(value)}</div>
    ${note ? `<div style="font-size:11px;color:#64748b;
      margin-top:4px">${esc(note)}</div>` : ''}
  </div>
`;

const riskCards = risks.map((risk, i) => `
  <div style="
    padding:14px 16px;
    margin-bottom:10px;
    border:1px solid #e2e8f0;
    border-left:4px solid #d97706;
    border-radius:8px;
    background:#fff;
    display:flex;gap:12px;
  ">
    <span style="font-weight:800;color:#b45309">
      ${String(i + 1).padStart(2, '0')}
    </span>
    <div style="font-size:13px;line-height:1.7">
      ${esc(risk)}
    </div>
  </div>
`).join('');

const questionCards = questions.map((question, i) => `
  <div style="
    display:flex;gap:14px;
    padding:14px 0;
    border-bottom:1px solid #e2e8f0;
  ">
    <div style="
      min-width:30px;height:30px;
      border-radius:50%;
      background:#e0e7ff;color:#3730a3;
      display:flex;align-items:center;
      justify-content:center;font-weight:800;
      font-size:12px;
    ">${i + 1}</div>
    <div style="font-size:13px;line-height:1.7;
      padding-top:4px">${esc(question)}</div>
  </div>
`).join('');

const verdict = report.score_provisional
  ? 'PROVISIONAL INVESTMENT ASSESSMENT'
  : 'INVESTMENT ASSESSMENT';

const html = `
<div style="
  max-width:920px;
  margin:0 auto;
  padding:36px 24px;
  font-family:Arial,Helvetica,sans-serif;
  color:#1e293b;
  background:#ffffff;
  text-align:left;
  line-height:1.65;
">

  <div style="
    display:flex;justify-content:space-between;
    align-items:flex-start;gap:15px;
    border-bottom:2px solid #0f172a;
    padding-bottom:20px;
  ">
    <div>
      <div style="
        color:#64748b;font-size:11px;
        letter-spacing:2.5px;font-weight:800;
      ">GERMAN REAL ESTATE · INVESTMENT RESEARCH</div>
      <h1 style="
        font-size:29px;line-height:1.25;
        margin:12px 0 8px;color:#0f172a;
      ">${esc(title)}</h1>
      <div style="color:#64748b;font-size:13px">
        ${esc(location)}
      </div>
    </div>
    <div style="
      border:1px solid #cbd5e1;
      border-radius:8px;padding:9px 12px;
      font-size:10px;font-weight:800;
      color:#475569;white-space:nowrap;
    ">INVESTMENT MEMO</div>
  </div>

  <div style="margin-top:26px">
    <div style="
      font-size:11px;font-weight:800;
      letter-spacing:1.5px;color:#64748b;
      margin-bottom:12px;
    ">01 / PROPERTY SNAPSHOT</div>

    <div style="
      display:grid;
      grid-template-columns:repeat(2,minmax(0,1fr));
      gap:12px;
    ">
      ${metric('Asking Price', money(price))}
      ${metric('Living Area',
        area === null ? 'Not available' : num(area, 2) + ' m²')}
      ${metric('Asking Price / m²', money(priceSqm))}
      ${metric('Gross Rental Yield',
        yieldPct === null ? 'N/A' : num(yieldPct, 2) + '%',
        yieldPct === null ? 'Rent not verified' : 'Based on stated rent')}
    </div>
  </div>

  <div style="
    margin-top:28px;
    padding:24px;
    border:1px solid #e2e8f0;
    border-radius:14px;
    background:${rating.bg};
  ">
    <div style="
      font-size:11px;font-weight:800;
      letter-spacing:1.5px;color:#64748b;
    ">02 / INVESTMENT ATTRACTIVENESS</div>

    <div style="
      display:flex;align-items:center;
      gap:22px;margin:15px 0;
    ">
      <div style="
        font-size:52px;line-height:1;
        font-weight:800;color:${rating.color};
      ">${score}<span style="
        font-size:24px;color:#94a3b8">/7</span></div>
      <div style="flex:1">
        <div style="
          color:${rating.color};
          font-size:15px;font-weight:800;
          margin-bottom:10px;
        ">${rating.label}</div>
        <div style="display:flex;gap:5px">${bars}</div>
      </div>
    </div>

    <div style="
      font-size:10px;font-weight:800;
      color:#64748b;letter-spacing:1px;
      margin-bottom:9px;
    ">${verdict}</div>

    <p style="margin:0;font-size:13px;line-height:1.8">
      ${esc(report.score_reason)}
    </p>
  </div>

  <div style="margin-top:30px">
    <div style="
      font-size:11px;font-weight:800;
      letter-spacing:1.5px;color:#64748b;
    ">03 / INVESTOR VALUE THESIS</div>
    <h2 style="font-size:21px;color:#0f172a;margin:8px 0 12px">
      Investment rationale
    </h2>
    <p style="
      font-size:14px;line-height:1.9;
      margin:0;white-space:pre-line;
    ">${esc(report.value_thesis)}</p>
  </div>

  <div style="margin-top:30px">
    <div style="
      font-size:11px;font-weight:800;
      letter-spacing:1.5px;color:#64748b;
    ">04 / RISK ASSESSMENT</div>
    <h2 style="font-size:21px;color:#0f172a;margin:8px 0 15px">
      Principal investment risks
    </h2>
    ${riskCards || '<p>No risks provided.</p>'}
  </div>

  <div style="margin-top:30px">
    <div style="
      font-size:11px;font-weight:800;
      letter-spacing:1.5px;color:#64748b;
    ">05 / DUE DILIGENCE</div>
    <h2 style="font-size:21px;color:#0f172a;margin:8px 0 12px">
      Questions for the seller / broker
    </h2>
    ${questionCards || '<p>No questions provided.</p>'}
  </div>

  <div style="
    margin-top:34px;padding:18px;
    background:#f8fafc;border-radius:10px;
    border:1px solid #e2e8f0;
    font-size:11px;color:#64748b;
  ">
    <div><b>Source document:</b> ${esc(sourceName)}</div>
    <div><b>Retrieved reference records:</b> ${referenceCount}</div>
    <div><b>Report generated:</b> ${
      new Date().toISOString().slice(0, 10)
    }</div>
    <p style="margin-bottom:0">
      This AI-generated report is an initial investment screening,
      not a certified valuation or legal, tax, or financial advice.
      Property claims, comparables, costs and assumptions require
      independent verification before an investment decision.
    </p>
  </div>
</div>
`;

return [{
  json: {
    investment_report_html: html,
    investment_report: [
      `PROPERTY INVESTMENT REPORT: ${title}`,
      `Attractiveness: ${score}/7`,
      report.score_reason,
      `VALUE THESIS: ${report.value_thesis}`,
      `RISKS:\n${risks.join('\n')}`,
      `BROKER QUESTIONS:\n${questions.join('\n')}`
    ].join('\n\n'),
    attractiveness_score: score,
    property_title: title,
    report,
    reference_count: referenceCount
  }
}];

const formatted = $input.first().json;

const pdf = $('Code in JavaScript1').first().json;

// Generate a unique property ID without crypto
const propertyId = [
  'property',
  Date.now().toString(36),
  Math.random().toString(36).slice(2, 12)
].join('-');

return [{
  json: {
    ...formatted,
    property_id: propertyId,
    source_filename: pdf.source_filename || 'Uploaded PDF',
    property_text: pdf.property_text || '',
    report_json: JSON.stringify(formatted.report),
    created_at: new Date().toISOString()
  }
}];

// ============================================================
// VALIDATE MARKET COMPARABLES
// Dynamic German Property Investment Evaluator
//
// Handles 0-3+ extracted candidates safely.
// No hardcoded property, city, or postcode.
// ============================================================

// 1. READ NEBIUS RESPONSE

const response = $input.first().json;

const subject = $('CD_Prepare Market Search')
  .first().json.market_search;

if (!subject) {
  throw new Error('Missing subject property');
}

let raw = response.choices?.[0]?.message?.content;

if (typeof raw !== 'string') {
  throw new Error('Nebius returned no JSON content');
}

raw = raw.trim()
  .replace(/^```(?:json)?\s*/i, '')
  .replace(/\s*```$/, '');

let parsed;

try {
  parsed = JSON.parse(raw);
} catch (error) {
  throw new Error(
    'Invalid Nebius JSON: ' + error.message
  );
}

// 2. HELPERS

function clean(value) {
  return String(value ?? '').trim();
}

function normalize(value) {
  return clean(value)
    .toLowerCase()
    .replace(/ä/g, 'ae')
    .replace(/ö/g, 'oe')
    .replace(/ü/g, 'ue')
    .replace(/ß/g, 'ss');
}

function positiveNumber(value) {
  if (value === null ||
      value === undefined ||
      value === '') {
    return null;
  }

  const n = Number(value);

  return Number.isFinite(n) && n > 0
    ? n
    : null;
}

function normalizeType(value) {
  const s = normalize(value);

  if (/mehrgeneration|generationenhaus/.test(s))
    return 'multigenerational_house';

  if (/mehrfamilien|zinshaus|multi.family/.test(s))
    return 'multi_family_house';

  if (/doppelhaus|\bdhh\b|semi.detached/.test(s))
    return 'semi_detached_house';

  if (/reihenend|reiheneck|end.terrace/.test(s))
    return 'end_terrace_house';

  if (/reihenhaus|reihenmittel|stadthaus|townhouse|terraced/.test(s))
    return 'terraced_house';

  if (/einfamilien|freistehend|detached.house/.test(s))
    return 'detached_house';

  if (/wohnung|apartment|maisonette|penthouse|flat/.test(s))
    return 'apartment';

  return s;
}

function isDirectListing(url) {
  const u = clean(url).toLowerCase();

  if (!/^https?:\/\/[^/\s]+\/.+/.test(u)) {
    return false;
  }

  if (
    /\/suche\/|\/search\/|\/immobilienpreise\//.test(u) ||
    /\/s\/(?:wohnung|haus|house|apartment)\//.test(u)
  ) {
    return false;
  }

  // Known direct-listing patterns
  return (
    /immobilienscout24\.de\/expose\//.test(u) ||
    /immowelt\.de\/expose\//.test(u) ||
    /immobilien\.sparkasse\.de\/expose\//.test(u) ||
    /leverage\.immo\/immobilien\/objekt\//.test(u) ||
    /clever-immobilien\.de\/deutschland\/.+\.html/.test(u) ||
    /\/immobilien\/[^/]+\/?$/.test(u) ||
    /\/objekt\/[^/]+\/?$/.test(u)
  );
}

function median(values) {
  if (!values.length) return null;

  const sorted = [...values].sort((a, b) => a - b);
  const middle = Math.floor(sorted.length / 2);

  return sorted.length % 2
    ? sorted[middle]
    : (sorted[middle - 1] + sorted[middle]) / 2;
}

// 3. MATCHING CRITERIA

const subjectArea = positiveNumber(
  subject.living_area_sqm
);

const subjectPrice = positiveNumber(
  subject.asking_price_eur
);

if (!subjectArea || !subjectPrice) {
  throw new Error('Invalid subject area or price');
}

const minArea = subjectArea * 0.75;
const maxArea = subjectArea * 1.25;

const targetCount = Math.max(
  1,
  Number(subject.target_comparable_count) || 3
);

const subjectType = normalizeType(
  subject.property_type
);

const subjectPostcode = clean(subject.postcode);
const subjectNeighborhood = normalize(
  subject.neighborhood
);

const priceTolerance =
  Number(subject.subject_price_tolerance_eur ?? 1000);

const areaTolerance =
  Number(subject.subject_area_tolerance_sqm ?? 2);

// 4. VALIDATE EXTRACTED COMPARABLES

const valid = [];
const rejected = Array.isArray(parsed.rejected_candidates)
  ? [...parsed.rejected_candidates]
  : [];

const seenUrls = new Set();

for (const c of (parsed.comparables || [])) {
  const reasons = [];

  const title = clean(c.title);
  const url = clean(c.url);
  const location = clean(c.location);

  const price = positiveNumber(c.asking_price_eur);
  const area = positiveNumber(c.living_area_sqm);

  const type = normalizeType(c.property_type);

  if (!isDirectListing(url)) {
    reasons.push('Not a recognized direct listing URL');
  }

  if (!price) {
    reasons.push('Missing asking price');
  }

  if (!area) {
    reasons.push('Missing living area');
  }

  if (type !== subjectType) {
    reasons.push('Property type mismatch');
  }

  if (area && (area < minArea || area > maxArea)) {
    reasons.push('Living area outside preferred range');
  }

  const normalizedLocation = normalize(location);

  const postcodeMatch =
    Boolean(subjectPostcode) &&
    normalizedLocation.includes(subjectPostcode);

  const neighborhoodMatch =
    Boolean(subjectNeighborhood) &&
    normalizedLocation.includes(subjectNeighborhood);

  if (!postcodeMatch && !neighborhoodMatch) {
    reasons.push('Location not established');
  }

  if (price && area) {
    if (
      Math.abs(price - subjectPrice) <= priceTolerance &&
      Math.abs(area - subjectArea) <= areaTolerance &&
      (postcodeMatch || neighborhoodMatch)
    ) {
      reasons.push('Likely subject property duplicate');
    }
  }

  const urlKey = url.toLowerCase()
    .split('#')[0]
    .split('?')[0];

  if (seenUrls.has(urlKey)) {
    reasons.push('Duplicate URL');
  }

  const candidate = {
    title,
    url,
    location,
    property_type: type,
    construction_status:
      c.construction_status || 'unknown',
    asking_price_eur: price,
    living_area_sqm: area,
    price_per_sqm:
      price && area
        ? Math.round(price / area)
        : null,
    verification_status: 'search_snippet_only'
  };

  if (reasons.length) {
    rejected.push({
      ...candidate,
      reason: reasons.join('; ')
    });
    continue;
  }

  seenUrls.add(urlKey);
  valid.push(candidate);
}

// 5. SELECT UP TO TARGET COUNT

const comparables = valid.slice(0, targetCount);

// Provisional median only if >= 3 candidates
const provisionalMedian =
  comparables.length >= 3
    ? median(
        comparables.map(c => c.price_per_sqm)
      )
    : null;

const subjectPriceSqm = Math.round(
  subjectPrice / subjectArea
);

const differencePct =
  provisionalMedian !== null
    ? Math.round(
        (
          (subjectPriceSqm - provisionalMedian) /
          provisionalMedian
        ) * 1000
      ) / 10
    : null;

// The fallback is a sourced, provisional area benchmark, not an observed comparable.
let benchmark = null;
const b = parsed.benchmark;
const results = $('Tavily - Find Additional Comparables').first().json.results || [];
if (comparables.length < 3 && b && typeof b === 'object') {
  const url = clean(b.source_url), quote = clean(b.quote);
  const source = results.find(r => clean(r.url) === url);
  const text = source ? clean((source.title || '') + ' ' + (source.content || '')) : '';
  const norm = t => normalize(t).replace(/\s+/g, ' ');
  const cityAliases = {cologne:'koeln',munich:'muenchen',dusseldorf:'duesseldorf',hanover:'hannover',nuremberg:'nuernberg'};
  const city = cityAliases[norm(subject.city)] || norm(subject.city);
  const isApartment = subjectType === 'apartment';
  const typeOK = isApartment ? /wohnung|apartment|eigentumswohnung/i.test(quote) : /haus|haeuser|häuser|hauspreise|house/i.test(quote);
  const quoteInSource = quote.length >= 15 && norm(text).includes(norm(quote));
  const benchmarkWords = /durchschnitt|durchschnittlich|mittelwert|median|average|medianpreis/i.test(quote);
  const unit = /(?:€|eur|euro)\s*(?:\/|pro|je)\s*(?:m²|m2|qm|quadratmeter)|(?:m²|m2|qm|quadratmeter)\s*(?:\/|pro|je)?\s*(?:€|eur|euro)|quadratmeterpreis[^\n]{0,80}(?:€|eur|euro)/i.test(quote);
  const numberTokens = quote.match(/\d[\d.,\s]*/g) || [];
  const parseGerman = t => { let q=t.replace(/\s/g,''); if (/^\d{1,3}(\.\d{3})+(,\d+)?$/.test(q)) q=q.replace(/\./g,'').replace(',','.'); else if (/^\d{1,3}(,\d{3})+(\.\d+)?$/.test(q)) q=q.replace(/,/g,''); else q=q.replace(',','.'); return Number(q); };
  const price = Number(b.price_per_sqm);
  const priceMatches = numberTokens.some(t => Math.abs(parseGerman(t)-price) < 1);
  const isPurchase = !/mietpreis|kaltmiete|warmmiete|mietwohnung|mietspiegel|rent per/i.test(quote);
  const individual = /\/expose\/|\/exposé\/|\/objekt\//i.test(url);
  if (source && /^https:\/\//i.test(url) && city && norm(quote).includes(city) && typeOK && quoteInSource && benchmarkWords && unit && isPurchase && !individual && Number.isFinite(price) && price >= 300 && price <= 50000 && priceMatches) {
    const period = clean(b.period);
    benchmark = {source_url:url, source_title:clean(source.title), quote, price_per_sqm:price,
      period:period && norm(text).includes(norm(period)) ? period : null,
      property_category:isApartment ? 'apartment' : 'house',
      location_scope:subject.neighborhood && norm(text).includes(norm(subject.neighborhood)) ? 'neighborhood mentioned in source; verify metric scope' : 'city; neighborhood specificity unconfirmed',
      condition_scope:'condition adjustment not verified',
      estimated_price_eur:Math.round(price * subjectArea),
      retrieved_at:subject.search_date || null};
  }
}

// 6. RETURN STRUCTURED OUTPUT

return [{
  json: {
    subject_property: subject,
    benchmark,

    comparables,
    comparable_count: comparables.length,

    rejected_candidates: rejected,
    rejected_count: rejected.length,

    provisional_market_median_per_sqm:
      provisionalMedian,

    provisional_snippet_median_per_sqm:
      provisionalMedian,

    subject_price_per_sqm: subjectPriceSqm,

    provisional_price_difference_pct:
      differencePct,

    market_median_per_sqm: null,
    market_confidence: 'unverified',
    benchmark_usable_for_scoring: false,

    market_analysis_status:
      comparables.length === 0
        ? 'Insufficient comparable evidence'
        : comparables.length < 3
          ? 'Fewer than 3 comparable candidates'
          : 'Preliminary asking-price comparison only'
  }
}];

