// ====================================================
// PREPARE ADDITIONAL COMPARABLES
// Dynamic candidate observations from Tavily Search
// ====================================================

const response = $input.first().json;
const results = response.results || [];

const subject = $('CD_Prepare Market Search')
  .first().json.market_search;

function parseGerman(value) {
  if (value == null) return null;

  const s = String(value)
    .replace(/\s/g, '')
    .replace(/\./g, '')
    .replace(',', '.');

  const n = Number(s);
  return Number.isFinite(n) ? n : null;
}

function normalize(value) {
  return String(value || '')
    .toLowerCase()
    .replace(/ö/g, 'o')
    .replace(/ü/g, 'u')
    .replace(/ä/g, 'a')
    .replace(/ß/g, 'ss');
}

function isLocationMatch(text) {
  const s = normalize(text);
  const neighborhood = normalize(subject.neighborhood);
  const postcode = String(subject.postcode || '');

  return (
    (postcode && s.includes(postcode)) ||
    (neighborhood && s.includes(neighborhood))
  );
}

function typeMatches(text) {
  const s = normalize(text);

  const patterns = {
    apartment: /wohnung|apartment|etagenwohnung|dachgeschoss|erdgeschoss|maisonette/,
    semi_detached_house: /doppelhaus|\bdhh\b/,
    detached_house: /einfamilienhaus|freistehend/,
    terraced_house: /reihenhaus|reihenmittelhaus/,
    end_terrace_house: /reihenendhaus/,
    multi_family_house: /mehrfamilienhaus/,
    multigenerational_house: /mehrgenerationenhaus/
  };

  return patterns[subject.property_type]
    ? patterns[subject.property_type].test(s)
    : false;
}

const observations = [];
const diagnostics = [];

for (const result of results) {
  const title = String(result.title || '');
  const snippet = String(result.content || '');
  const url = String(result.url || '');
  const text = title + ' ' + snippet;

  const reasons = [];

  if (!isLocationMatch(text + ' ' + url)) {
    reasons.push('Location not established');
  }

  if (!typeMatches(text)) {
    reasons.push('Property type mismatch');
  }

  if (/kaltmiete|warmmiete|wohnung mieten|haus mieten/i.test(text) &&
      !/wohnung zum kauf|kaufpreis/i.test(text)) {
    reasons.push('Rental listing');
  }

  const categoryPage =
    /\/suche\/|\/search\/|\/s\/wohnung\/|\/s\/haus\/|\/wohnung\/kaufen$/i
      .test(url) ||
    /\d+\s+(?:wohnungen|angebote|immobilien)/i.test(title);

  const priceMatches = [
    ...snippet.matchAll(
      /(\d{1,3}(?:\.\d{3})+(?:,\d{1,2})?)\s*€/g
    )
  ];

  const areaMatches = [
    ...snippet.matchAll(
      /(\d{2,3}(?:[,.]\d{1,2})?)\s*m[²2]/gi
    )
  ];

  // Only pair when the snippet contains one
  // plausible price and one plausible living area.
  const prices = priceMatches
    .map(m => parseGerman(m[1]))
    .filter(v => v >= 50000 && v <= 10000000);

  const areas = areaMatches
    .map(m => parseGerman(m[1]))
    .filter(v => v >= 20 && v <= 1000);

  const uniquePrices = [...new Set(prices)];
  const uniqueAreas = [...new Set(areas)];

  const price = uniquePrices.length === 1
    ? uniquePrices[0]
    : null;

  const area = uniqueAreas.length === 1
    ? uniqueAreas[0]
    : null;

  if (price === null || area === null) {
    reasons.push('Price/area pairing ambiguous');
  }

  if (price !== null && area !== null) {
    if (
      Math.abs(price - subject.asking_price_eur) < 1000 &&
      Math.abs(area - subject.living_area_sqm) < 2
    ) {
      reasons.push('Subject property');
    }

    const minArea = subject.living_area_sqm * 0.7;
    const maxArea = subject.living_area_sqm * 1.3;

    if (area < minArea || area > maxArea) {
      reasons.push('Area outside extended range');
    }
  }

  const observation = {
    title,
    url,
    asking_price_eur: price,
    living_area_sqm: area,
    price_per_sqm:
      price !== null && area !== null
        ? Math.round(price / area)
        : null,
    source_type: categoryPage
      ? 'search_category_page'
      : 'possible_direct_listing',
    verification_status: categoryPage
      ? 'needs_direct_listing_url'
      : 'search_snippet_only',
    evidence: snippet
  };

  diagnostics.push({
    title,
    url,
    rejected_reasons: reasons
  });

  if (reasons.length) continue;

  observations.push(observation);
}

return [{
  json: {
    subject_property: subject,
    additional_candidates: observations,
    candidate_count: observations.length,
    total_search_results: results.length,
    diagnostics,
    market_confidence: 'unverified',
    benchmark_usable_for_scoring: false
  }
}];

const results = $input.first().json.results || [];

const targets = results.filter(r =>
  /164830327|168092721/.test(r.url || '')
);

return targets.map(r => {
  const title = String(r.title || '');
  const text = String(r.content || '');

  const priceMatch = text.match(
    /(\d{1,3}(?:\.\d{3})+(?:,\d{1,2})?)\s*€/
  );

  const areaMatch = text.match(
    /(\d{2,3}(?:[,.]\d{1,2})?)\s*m[²2]\s*\.?\s*Wohnfläche/i
  );

  return {
    json: {
      title,
      url: r.url,
      snippet: text,

      direct_listing:
        /immobilienscout24\.de\/expose\/\d+/i.test(r.url),

      property_type_match:
        /Doppelhaushälfte|DHH/i.test(title + ' ' + text),

      sale_match:
        /zum Kauf|Haus\/Kauf/i.test(text),

      price_found: priceMatch?.[1] || null,
      area_found: areaMatch?.[1] || null
    }
  };
});

// ======================================================
// PREPARE MARKET REPORT SECTION
// Dynamic German property investment report
// ======================================================

const market = $input.first().json;

const original = $('Format Investment Report')
  .first().json;

const subject = market.subject_property || {};
const comparables = market.comparables || [];
const leads = market.additional_leads || [];
const benchmark = market.benchmark || null;

// ------------------------------------------------------
// HELPERS
// ------------------------------------------------------

function escapeHtml(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function euro(value) {
  if (
    value === null ||
    value === undefined ||
    !Number.isFinite(Number(value))
  ) {
    return 'N/A';
  }

  return new Intl.NumberFormat('de-DE', {
    style: 'currency',
    currency: 'EUR',
    maximumFractionDigits: 0
  }).format(Number(value));
}

function number(value, digits = 0) {
  if (
    value === null ||
    value === undefined ||
    !Number.isFinite(Number(value))
  ) {
    return 'N/A';
  }

  return new Intl.NumberFormat('de-DE', {
    maximumFractionDigits: digits
  }).format(Number(value));
}

function safeUrl(value) {
  const url = String(value || '').trim();

  return /^https:\/\/[a-z0-9.-]+\//i.test(url)
    ? escapeHtml(url)
    : '';
}

// ------------------------------------------------------
// SUBJECT METRICS
// ------------------------------------------------------

const subjectPrice = subject.asking_price_eur;
const subjectArea = subject.living_area_sqm;
const subjectPriceSqm = subject.asking_price_per_sqm;

const provisionalMedian =
  market.provisional_market_median_per_sqm;

const priceDifference =
  market.provisional_price_difference_pct;

const benchmarkUsable =
  market.benchmark_usable_for_scoring === true;

// A single comparable is not a reliable market median.
const hasIndicativeMedian =
  comparables.length >= 3 &&
  provisionalMedian !== null &&
  provisionalMedian !== undefined;

// ------------------------------------------------------
// COMPARABLE ROWS
// ------------------------------------------------------

const comparableRows = comparables.map((c, index) => {
  const link = safeUrl(c.url);

  const title = escapeHtml(
    c.title || `Comparable ${index + 1}`
  );

  const titleHtml = link
    ? `<a href="${link}" target="_blank"
         rel="noopener noreferrer">${title}</a>`
    : title;

  return `
    <tr>
      <td>
        <strong>${titleHtml}</strong>
        <div style="font-size:11px;color:#64748b">
          ${escapeHtml(c.location || 'Location not confirmed')}
        </div>
      </td>
      <td>${euro(c.asking_price_eur)}</td>
      <td>${number(c.living_area_sqm, 2)} m²</td>
      <td>${euro(c.price_per_sqm)}</td>
      <td style="color:#b45309;font-size:11px">
        Unverified
      </td>
    </tr>
  `;
}).join('');

// ------------------------------------------------------
// UNRESOLVED LEADS
// ------------------------------------------------------

const leadRows = leads.map((c, index) => {
  const link = safeUrl(c.url);

  const title = escapeHtml(
    c.title || `Market lead ${index + 1}`
  );

  const titleHtml = link
    ? `<a href="${link}" target="_blank"
         rel="noopener noreferrer">${title}</a>`
    : title;

  return `
    <tr>
      <td>${titleHtml}</td>
      <td>${euro(c.asking_price_eur)}</td>
      <td>${number(c.living_area_sqm, 2)} m²</td>
      <td>${euro(c.price_per_sqm)}</td>
      <td style="font-size:11px;color:#b45309">
        Needs direct listing
      </td>
    </tr>
  `;
}).join('');

// ------------------------------------------------------
// MARKET INTERPRETATION
// ------------------------------------------------------

let interpretation;

if (comparables.length === 0) {
  interpretation =
    'No sufficiently identifiable individual comparable listings were found. ' +
    (benchmark ? 'The sourced area benchmark below is a provisional reference, not a valuation.' : 'No sufficiently supported area benchmark was found.');
} else if (comparables.length < 3) {
  interpretation =
    `${comparables.length} individual listing candidate(s) ` +
    'were identified. This is insufficient for a reliable ' +
    'market benchmark. The reported asking prices are ' +
    'informational and have not been independently verified.';
} else {
  interpretation =
    'Three individual listing candidates were identified. ' +
    'Their asking-price comparison is preliminary because ' +
    'listing availability, property condition, and other ' +
    'price-relevant characteristics remain unverified.';
}

const medianHtml = hasIndicativeMedian
  ? euro(provisionalMedian) + '/m²'
  : 'Insufficient comparable evidence';

const differenceHtml =
  hasIndicativeMedian &&
  priceDifference !== null &&
  priceDifference !== undefined
    ? number(priceDifference, 1) + '%'
    : 'Not assessed';

// ------------------------------------------------------
// BUILD HTML SECTION
// ------------------------------------------------------

const marketHtml = `
<section class="market-comparison"
  style="margin-top:34px;padding-top:24px;
  border-top:2px solid #e2e8f0;text-align:left">

  <div style="font-size:11px;font-weight:800;
    letter-spacing:1.5px;color:#64748b">
    06 / MARKET COMPARISON
  </div>

  <h2 style="font-size:22px;color:#0f172a;
    margin:8px 0 12px">
    Comparable Properties & Market Position
  </h2>

  <p style="font-size:13px;color:#475569">
    Market research for
    <strong>${escapeHtml(subject.neighborhood || '')},
    ${escapeHtml(subject.city || '')}</strong>.
    Subject property:
    ${number(subjectArea, 2)} m²,
    asking price ${euro(subjectPrice)}.
  </p>

  <div style="display:grid;
    grid-template-columns:repeat(2,minmax(0,1fr));
    gap:12px;margin:20px 0">

    <div style="padding:18px;background:#f8fafc;
      border:1px solid #e2e8f0;border-radius:10px">
      <div style="font-size:11px;color:#64748b">
        SUBJECT ASKING PRICE / M²
      </div>
      <div style="font-size:24px;font-weight:800">
        ${euro(subjectPriceSqm)}
      </div>
    </div>

    <div style="padding:18px;background:#f8fafc;
      border:1px solid #e2e8f0;border-radius:10px">
      <div style="font-size:11px;color:#64748b">
        PROVISIONAL COMPARABLE MEDIAN
      </div>
      <div style="font-size:20px;font-weight:800">
        ${medianHtml}
      </div>
    </div>

  </div>

  <p style="font-size:13px;line-height:1.8">
    <strong>Market assessment:</strong>
    ${escapeHtml(interpretation)}
  </p>

  <p style="font-size:12px;color:#475569">
    Subject price difference versus candidate median:
    <strong>${differenceHtml}</strong>
  </p>

  ${benchmark ? `<div style="margin:18px 0;padding:16px;border:1px solid #bfdbfe;background:#eff6ff;border-radius:8px;font-size:13px;line-height:1.6">
    <strong>Indicative location benchmark: ${euro(benchmark.price_per_sqm)}/m²</strong><br>
    Area-based estimate: <strong>${euro(benchmark.estimated_price_eur)}</strong> (${number(subjectArea,2)} m² × ${euro(benchmark.price_per_sqm)}/m²).<br>
    Source: <a href="${safeUrl(benchmark.source_url)}" target="_blank" rel="noopener noreferrer">${escapeHtml(benchmark.source_title || benchmark.source_url)}</a>;
    source period: ${escapeHtml(benchmark.period || 'not stated in the retrieved excerpt')}; retrieved ${escapeHtml((benchmark.retrieved_at || '').slice(0,10))}.<br>
    Category: ${escapeHtml(benchmark.property_category)}; ${escapeHtml(benchmark.location_scope)}; ${escapeHtml(benchmark.condition_scope)}.
    The source may cover a broader area and property class than the subject. No unsupported condition, subtype, or land-value adjustment has been applied. This is a broad reference, not a valuation or a verified comparable; confirm source methodology and current data before relying on it.
    <blockquote style="margin:8px 0 0">${escapeHtml(benchmark.quote)}</blockquote>
  </div>` : ''}

  <h3 style="font-size:16px;margin-top:24px">
    Individual listing candidates
  </h3>

  ${
    comparables.length
      ? `<div style="overflow-x:auto">
          <table style="width:100%;border-collapse:collapse;
            font-size:12px;text-align:left">
            <thead>
              <tr style="background:#f1f5f9">
                <th>Property</th>
                <th>Price</th>
                <th>Area</th>
                <th>€/m²</th>
                <th>Status</th>
              </tr>
            </thead>
            <tbody>${comparableRows}</tbody>
          </table>
        </div>`
      : `<p style="font-size:13px;color:#64748b">
           No individual listing candidates available.
         </p>`
  }

  ${
    leads.length
      ? `
        <h3 style="font-size:16px;margin-top:28px">
          Additional market leads
        </h3>

        <p style="font-size:12px;color:#64748b">
          The following observations come from search-result
          pages and are excluded from the market benchmark.
          Some may describe the same property.
        </p>

        <div style="overflow-x:auto">
          <table style="width:100%;border-collapse:collapse;
            font-size:12px;text-align:left">
            <thead>
              <tr style="background:#f1f5f9">
                <th>Source</th>
                <th>Price</th>
                <th>Area</th>
                <th>€/m²</th>
                <th>Status</th>
              </tr>
            </thead>
            <tbody>${leadRows}</tbody>
          </table>
        </div>
      `
      : ''
  }

  <div style="margin-top:22px;padding:15px;
    background:#fff7ed;border:1px solid #fed7aa;
    border-radius:8px;font-size:12px;
    line-height:1.7;color:#9a3412">

    <strong>Evidence limitation:</strong>
    Market observations are derived from online search
    snippets. Listing status, specifications, construction
    condition and asking prices require verification.
    Category-page observations are not treated as
    independently confirmed listings.

    ${
      benchmarkUsable
        ? 'The benchmark has been marked usable by upstream validation.'
        : 'The market benchmark is not approved for investment scoring.'
    }

  </div>

</section>
`;

// ------------------------------------------------------
// RETURN ORIGINAL REPORT + MARKET SECTION
// ------------------------------------------------------

return [{
  json: {
    ...original,

    market_comparison_html: marketHtml,

    comparables,

    additional_leads: leads,

    market_summary: {
      benchmark,
      comparable_count: comparables.length,
      lead_count: leads.length,
      subject_price_per_sqm: subjectPriceSqm,
      provisional_median_per_sqm:
        hasIndicativeMedian ? provisionalMedian : null,
      price_difference_pct:
        hasIndicativeMedian ? priceDifference : null,
      confidence: market.market_confidence,
      benchmark_usable_for_scoring: benchmarkUsable
    }
  }
}];

// ASSEMBLE FINAL INVESTMENT REPORT

const data = $input.first().json;

const originalHtml = String(
  data.investment_report_html || ''
);

const marketHtml = String(
  data.market_comparison_html || ''
);

if (!originalHtml) {
  throw new Error('Original investment report HTML missing');
}

// Insert market comparison before the report footer.
// Existing report has a source-document footer near
// the end of the HTML.

const footerMarker = '<div style="\n    margin-top:34px';

let finalHtml;

if (originalHtml.includes(footerMarker)) {
  finalHtml = originalHtml.replace(
    footerMarker,
    marketHtml + '\n\n' + footerMarker
  );
} else {
  // Fallback: insert before final outer closing div.
  const lastDiv = originalHtml.lastIndexOf('</div>');

  finalHtml = lastDiv >= 0
    ? originalHtml.slice(0, lastDiv) +
      marketHtml + '\n' +
      originalHtml.slice(lastDiv)
    : originalHtml + marketHtml;
}

// Add styling for the market comparison table
const marketStyles = `
<style>
.market-comparison {
  margin-top: 32px;
  padding-top: 24px;
  border-top: 2px solid #e2e8f0;
}

.market-comparison h2 {
  font-size: 21px;
  color: #0f172a;
  margin-bottom: 16px;
}

