  width: 100%;
  border-collapse: collapse;
  font-size: 12px;
  margin-top: 18px;
}

.market-comparison th {
  background: #f1f5f9;
  color: #334155;
  padding: 12px;
  text-align: left;
  border-bottom: 2px solid #cbd5e1;
}

.market-comparison td {
  padding: 12px;
  border-bottom: 1px solid #e2e8f0;
  vertical-align: top;
}

.market-comparison a {
  color: #2563eb;
  text-decoration: underline;
}

.market-disclaimer {
  font-size: 11px;
  color: #64748b;
  margin-top: 16px;
  line-height: 1.7;
}
</style>
`;

finalHtml = marketStyles + finalHtml;

return [{
  json: {
    ...data,
    final_investment_report_html: finalHtml,
    final_report_ready: true
  }
}];

// ============================================================
// PREPARE MARKET SEARCH - DYNAMIC VERSION
// German Property Investment Evaluator
// Compatible with n8n Code node
// ============================================================

// 1. INPUT


const input = $('Format Investment Report').first().json;

let report = input.report || {};

if (typeof report === 'string') {
  try {
    report = JSON.parse(report);
  } catch (error) {
    throw new Error(
      'Format Investment Report contains invalid report JSON'
    );
  }
}



if (typeof report === 'string') {
  try {
    report = JSON.parse(report);
  } catch (e) {
    report = {};
  }
}

// 2. HELPERS
function clean(value) {
  if (value === null || value === undefined) return '';
  return String(value).replace(/\s+/g, ' ').trim();
}

function number(value) {
  if (value === null || value === undefined || value === '') {
    return null;
  }

  if (typeof value === 'number') {
    return Number.isFinite(value) ? value : null;
  }

  let s = String(value)
    .replace(/[€\s]/g, '')
    .trim();

  if (s.includes(',') && s.includes('.')) {
    if (s.lastIndexOf(',') > s.lastIndexOf('.')) {
      s = s.replace(/\./g, '').replace(',', '.');
    } else {
      s = s.replace(/,/g, '');
    }
  } else if (s.includes(',')) {
    if (/^\d{1,3}(,\d{3})+$/.test(s)) {
      s = s.replace(/,/g, '');
    } else {
      s = s.replace(',', '.');
    }
  } else if (/^\d{1,3}(\.\d{3})+$/.test(s)) {
    s = s.replace(/\./g, '');
  }

  const n = Number(s);
  return Number.isFinite(n) ? n : null;
}

function first(...values) {
  for (const v of values) {
    if (v !== null && v !== undefined && v !== '') {
      return v;
    }
  }
  return null;
}

// 3. PROPERTY TYPE NORMALIZATION
function normalizeType(value) {
  const s = clean(value).toLowerCase();

  if (/mehrgeneration|multigeneration|generationenhaus/i.test(s)) {
    return 'multigenerational_house';
  }

  if (/mehrfamilien|multi.family|apartment.building/i.test(s)) {
    return 'multi_family_house';
  }

  if (/doppelhaus|semi.detached|\bdhh\b/i.test(s)) {
    return 'semi_detached_house';
  }

  if (/reihenend|end.terrace/i.test(s)) {
    return 'end_terrace_house';
  }

  if (/reihenhaus|reihenmittel|terraced|townhouse/i.test(s)) {
    return 'terraced_house';
  }

  if (/reihenhaus|reihenmittel|terraced|townhouse/i.test(s)) {
  return 'terraced_house';
  }

  if (/einfamilien|freistehend|detached.house/i.test(s)) {
    return 'detached_house';
  }

  if (/wohnung|apartment|etagenwohnung|maisonette/i.test(s)) {
    return 'apartment';
  }

  return 'unknown';
}

// 4. CONSTRUCTION STATUS NORMALIZATION
function normalizeCondition(value) {
  const s = clean(value).toLowerCase();

  if (/renovierungsbedürftig|sanierungsbedürftig|needs.renovation|fixer.upper/i.test(s)) {
    return 'needs_renovation';
  }

  if (/kernsanier|vollsanier|renoviert|saniert|modernisiert|refurbished/i.test(s)) {
    return 'renovated';
  }

  if (/neubau|new.construction|new.build|newly.built|erstbezug|kfw.40|kfw40/i.test(s)) {
    return 'new_construction';
  }

  if (/bestand|existing|altbau|gebraucht/i.test(s)) {
    return 'existing';
  }

  return 'unknown';
}

// 5. EXTRACT STRUCTURED PROPERTY DETAILS
const title = clean(first(
  report.property_title,
  input.property_title,
  report.title
));

const city = clean(first(
  report.city,
  report.location?.city,
  input.city
));

const neighborhood = clean(first(
  report.neighborhood,
  report.district,
  report.location?.neighborhood,
  input.neighborhood
));

const postcode = clean(first(
  report.postal_code,
  report.postcode,
  report.zip_code,
  input.postcode
));

const askingPrice = number(first(
  report.asking_price,
  report.asking_price_eur,
  input.asking_price_eur
));

const livingArea = number(first(
  report.living_area_sqm,
  report.living_area,
  input.living_area_sqm
));

const listedPriceSqm = number(first(
  report.price_per_sqm,
  report.asking_price_per_sqm,
  input.asking_price_per_sqm
));

const pricePerSqm =
  askingPrice !== null &&
  livingArea !== null &&
  livingArea > 0
    ? Math.round(askingPrice / livingArea)
    : listedPriceSqm;

// 6. IDENTIFY PROPERTY TYPE
let propertyType = normalizeType(first(
  report.property_type,
  report.building_type,
  input.property_type
));

if (propertyType === 'unknown') {
  propertyType = normalizeType(title);
}

// 7. IDENTIFY CONSTRUCTION STATUS
let constructionStatus = normalizeCondition(first(
  report.construction_status,
  report.condition,
  report.building_condition,
  input.construction_status
));

if (constructionStatus === 'unknown') {
  constructionStatus = normalizeCondition(title);
}

// 8. SEARCH TERM MAPPINGS
const typeTerms = {
  semi_detached_house: 'Doppelhaushälfte',
  detached_house: 'Einfamilienhaus',
  apartment: 'Eigentumswohnung',
  multi_family_house: 'Mehrfamilienhaus',
  multigenerational_house: 'Mehrgenerationenhaus',
  terraced_house: 'Reihenhaus',
  end_terrace_house: 'Reihenendhaus',
  unknown: 'Wohnimmobilie'
};

const conditionTerms = {
  new_construction: 'Neubau',
  renovated: 'saniert modernisiert',
  existing: 'Bestandsimmobilie',
  needs_renovation: 'renovierungsbedürftig',
  unknown: ''
};

const typeTerm = typeTerms[propertyType];
const conditionTerm = conditionTerms[constructionStatus];

const searchCity =
  city.toLowerCase() === 'cologne'
    ? 'Köln'
    : city;

// 9. BUILD DYNAMIC SEARCH QUERIES
const searchQuery = [
  typeTerm,
  conditionTerm,
  'kaufen',
  neighborhood,
  searchCity,
  postcode,
  livingArea
    ? 'ca. ' + Math.round(livingArea) + ' m²'
    : '',
  'Kaufpreis Wohnfläche'
].filter(Boolean).join(' ');

const broaderSearchQuery = [
  typeTerm,
  conditionTerm,
  'kaufen',
  searchCity,
  neighborhood || postcode,
  'Kaufpreis Wohnfläche'
].filter(Boolean).join(' ');

// 10. VALIDATION
const missingFields = [];

if (!city) missingFields.push('city');

if (propertyType === 'unknown') {
  missingFields.push('property_type');
}

if (!livingArea || livingArea <= 0) {
  missingFields.push('living_area_sqm');
}

if (!askingPrice || askingPrice <= 0) {
  missingFields.push('asking_price_eur');
}

// 11. MARKET SEARCH OBJECT
const market_search = {
  country: 'DE',

  property_title: title,

  city,
  postcode,
  neighborhood,

  property_type: propertyType,
  living_area_sqm: livingArea,

  asking_price_eur: askingPrice,
  asking_price_per_sqm: pricePerSqm,

  construction_status: constructionStatus,

  search_query: searchQuery,
  broader_search_query: broaderSearchQuery,

  min_comparable_area_sqm: livingArea
    ? Math.round(livingArea * 0.75)
    : null,

  max_comparable_area_sqm: livingArea
    ? Math.round(livingArea * 1.25)
    : null,

  subject_price_tolerance_eur: 1000,
  subject_area_tolerance_sqm: 2,

  target_comparable_count: 3,
  search_language: 'de',
  search_date: new Date().toISOString(),

  comparables: [],
  market_median_per_sqm: null,
  market_confidence: 'not_assessed',
  benchmark_usable_for_scoring: false,

  ready_for_market_search: missingFields.length === 0,
  missing_fields: missingFields
};

// 12. OUTPUT
return [{
  json: {
    market_search
  }
}];

