parameters.jsCode:
// ============================================================
// CD_Select Comparable Properties
// Dynamic German Real Estate Comparable Selection
//
// Subject: CD_Prepare Market Search
// Search:  TAVILY - Search Comparables
//
// No hardcoded city, property type, price or area.
// No URL constructor dependency.
// No external API calls.
// ============================================================

// 1. READ DATA FROM EXACT NODE NAMES

const response = $('TAVILY - Search Comparables')
  .first().json;

const prepared = $('CD_Prepare Market Search')
  .first().json;

const subject = prepared.market_search;

if (!subject) {
  throw new Error(
    'CD_Prepare Market Search returned no market_search'
  );
}

const results = Array.isArray(response.results)
  ? response.results
  : [];

// 2. HELPERS

function clean(value) {
  return String(value ?? '')
    .replace(/\s+/g, ' ')
    .trim();
}

function normalize(value) {
  return clean(value)
    .toLowerCase()
    .replace(/ä/g, 'ae')
    .replace(/ö/g, 'oe')
    .replace(/ü/g, 'ue')
    .replace(/ß/g, 'ss')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');
}

function positiveNumber(value) {
  if (value === null || value === undefined || value === '') {
    return null;
  }

  const n = Number(value);
  return Number.isFinite(n) && n > 0 ? n : null;
}

// URL parsing compatible with n8n Code node
function normalizeUrl(value) {
  const url = clean(value);

  if (!/^https?:\/\/[^\s/]+/i.test(url)) {
    return '';
  }

  const noFragment = url.split('#')[0];
  const parts = noFragment.split('?');
  const base = parts[0];

  if (parts.length === 1) return base;

  const params = parts.slice(1)
    .join('?')
    .split('&')
    .filter(param => {
      const key = param.split('=')[0].toLowerCase();

      return !(
        key.startsWith('utm_') ||
        key === 'fbclid' ||
        key === 'gclid'
      );
    });

  return params.length
    ? base + '?' + params.join('&')
    : base;
}

function getDomain(url) {
  const match = clean(url)
    .match(/^https?:\/\/([^/?#]+)/i);

  return match
    ? match[1].replace(/^www\./i, '').toLowerCase()
    : '';
}

function isCategoryPage(url, title) {
  const u = normalize(url);
  const t = normalize(title);

  return (
    /\/suche\/|\/search\/|\/immobilienpreise\//i.test(u) ||
    /\/s\/(?:wohnung|haus|house|apartment)\//i.test(u) ||
    /\/(?:wohnung|haus)\/kaufen\/?$/i.test(u) ||
    /\/(?:wohnung|haus)\/[^/]+\/kaufen\/?$/i.test(u) ||
    /\b\d+\s+(?:eigentumswohnungen|wohnungen|haeuser|immobilien|angebote)\b/i.test(t) ||
    /\b(?:suchauftrag|suchergebnisse|alle angebote)\b/i.test(t)
  );
}

function parseGermanNumber(value) {
  let s = clean(value).replace(/\s/g, '');

  if (s.includes(',') && s.includes('.')) {
    if (s.lastIndexOf(',') > s.lastIndexOf('.')) {
      s = s.replace(/\./g, '').replace(',', '.');
    } else {
      s = s.replace(/,/g, '');
    }
  } else if (s.includes(',')) {
    s = s.replace(',', '.');
  } else if (/^\d{1,3}(\.\d{3})+$/.test(s)) {
    s = s.replace(/\./g, '');
  }

  const n = Number(s);
  return Number.isFinite(n) ? n : null;
}

function extractPriceSignals(text) {
  const matches = [
    ...text.matchAll(
      /(\d{1,3}(?:\.\d{3})+(?:,\d{1,2})?|\d{5,8})\s*€/g
    )
  ];

  return matches
    .map(m => parseGermanNumber(m[1]))
    .filter(n => n !== null && n >= 30000);
}

function extractAreaSignals(text) {
  const matches = [
    ...text.matchAll(
      /(\d{2,4}(?:[,.]\d{1,2})?)\s*(?:m²|m2|qm)(?!\w)/gi
    )
  ];

  return matches
    .map(m => parseGermanNumber(m[1]))
    .filter(n => n !== null && n >= 15 && n <= 2000);
}

// 3. VALIDATE CURRENT SUBJECT PROPERTY

const missing = [];

const city = clean(subject.city);
const neighborhood = clean(subject.neighborhood);
const postcode = clean(subject.postcode);
const propertyType = clean(subject.property_type);

const subjectArea = positiveNumber(
  subject.living_area_sqm
);

const subjectPrice = positiveNumber(
  subject.asking_price_eur
);

if (!city) missing.push('city');

if (!postcode && !neighborhood) {
  missing.push('postcode_or_neighborhood');
}

if (!propertyType || propertyType === 'unknown') {
  missing.push('property_type');
}

if (!subjectArea) missing.push('living_area_sqm');
if (!subjectPrice) missing.push('asking_price_eur');

if (missing.length) {
  throw new Error(
    'Subject property missing: ' + missing.join(', ')
  );
}

// 4. DYNAMIC MATCHING CRITERIA

const minArea = subjectArea * 0.75;
const maxArea = subjectArea * 1.25;

const priceTolerance =
  positiveNumber(subject.subject_price_tolerance_eur)
  ?? 1000;

const areaTolerance =
  positiveNumber(subject.subject_area_tolerance_sqm)
  ?? 2;

const targetCount = Math.max(
  1,
  Math.min(
    10,
    Number(subject.target_comparable_count) || 3
  )
);

// 5. PROPERTY TYPE MATCHING

const typePatterns = {
  apartment:
    /wohnung|apartment|maisonette|penthouse|flat/i,

  semi_detached_house:
    /doppelhaus|\bdhh\b|semi.detached/i,

  detached_house:
    /einfamilienhaus|freistehend|detached.house/i,

  terraced_house:
    /reihenhaus|reihenmittelhaus|stadthaus|townhouse|terraced.house/i,

  end_terrace_house:
    /reihenendhaus|reiheneckhaus|end.terrace/i,

  multi_family_house:
    /mehrfamilienhaus|zinshaus|multi.family/i,

  multigenerational_house:
    /mehrgenerationenhaus|generationenhaus|multigenerational/i
};

const typePattern = typePatterns[propertyType];

// 6. LOCATION NORMALIZATION

const cityAliases = {
  cologne: ['koeln', 'cologne'],
  koeln: ['koeln', 'cologne'],
  munich: ['muenchen', 'munich'],
  muenchen: ['muenchen', 'munich'],
  dusseldorf: ['duesseldorf', 'dusseldorf'],
  duesseldorf: ['duesseldorf', 'dusseldorf'],
  nuremberg: ['nuernberg', 'nuremberg'],
  nuernberg: ['nuernberg', 'nuremberg'],
  hanover: ['hannover', 'hanover'],
  hannover: ['hannover', 'hanover']
};

const normalizedCity = normalize(city);
const normalizedNeighborhood = normalize(neighborhood);

const cityVariants =
  cityAliases[normalizedCity] ||
  [normalizedCity];

function checkLocation(text) {
  const s = normalize(text);

  return {
    city_match: cityVariants.some(
      v => v && s.includes(v)
    ),
    postcode_match:
      Boolean(postcode) && s.includes(postcode),
    neighborhood_match:
      Boolean(normalizedNeighborhood) &&
      s.includes(normalizedNeighborhood)
  };
}

// 7. PROCESS TAVILY RESULTS

const candidates = [];
const excluded = [];
const seenUrls = new Set();

for (let i = 0; i < results.length; i++) {
  const result = results[i];

  const title = clean(result.title);
  const snippet = clean(result.content);
  const url = normalizeUrl(result.url);

  const combinedText = [
    title,
    snippet,
    url
  ].join(' ');

  const normalizedText = normalize(combinedText);

  const location = checkLocation(combinedText);

  const reasons = [];
  const flags = [];

  if (!url) {
    reasons.push('invalid_url');
  }

  if (url && seenUrls.has(url)) {
    reasons.push('duplicate_url');
  }

  const categoryPage = isCategoryPage(url, title);

  if (categoryPage) {
    flags.push('category_page');
  }

  if (
    !location.postcode_match &&
    !location.neighborhood_match
  ) {
    flags.push('location_needs_verification');
  }

  if (
    !location.city_match &&
    !location.postcode_match
  ) {
    flags.push('city_needs_verification');
  }

  const typeMatch = typePattern
    ? typePattern.test(normalizedText)
    : false;

  if (!typeMatch) {
    flags.push('property_type_needs_verification');
  }

  // Exclude rental-only search results
  const rentalSignals =
    /kaltmiete|warmmiete|mietwohnung|zur miete|for rent/i
      .test(normalizedText);

  const saleSignals =
    /kaufpreis|zum kauf|kaufen|purchase price|for sale/i
      .test(normalizedText);

  if (rentalSignals && !saleSignals) {
    reasons.push('rental_only');
  }

  // Detect likely subject-property duplicates
  const prices = extractPriceSignals(snippet);
  const areas = extractAreaSignals(snippet);

  const priceMatch = prices.some(
    p => Math.abs(p - subjectPrice) <= priceTolerance
  );

  const areaMatch = areas.some(
    a => Math.abs(a - subjectArea) <= areaTolerance
  );

  const subjectTitle = normalize(
    subject.property_title
  );

  const exactTitleMatch =
    Boolean(subjectTitle) &&
    normalize(title) === subjectTitle;

  if (
    exactTitleMatch ||
    (
      priceMatch &&
      areaMatch &&
      (
        location.postcode_match ||
        location.neighborhood_match
      )
    )
  ) {
    flags.push('possible_subject_duplicate');
  }

  const candidate = {
    candidate_id: i + 1,

    title,
    url,
    snippet,

    source_domain: getDomain(url),

    search_relevance:
      typeof result.score === 'number'
        ? result.score
        : null,

    location_signals: location,
    property_type_signal: typeMatch,

    source_type: categoryPage
      ? 'search_category_page'
      : 'possible_individual_listing',

    verification_status: 'search_snippet_only',
    validation_flags: flags
  };

  if (reasons.length) {
    excluded.push({
      ...candidate,
      excluded_reasons: reasons
    });
    continue;
  }

  seenUrls.add(url);
  candidates.push(candidate);
}

// 8. PRIORITIZE SEARCH RESULTS

function priority(c) {
  let score = 0;

  if (c.location_signals.postcode_match) {
    score += 35;
  }

  if (c.location_signals.neighborhood_match) {
    score += 25;
  }

  if (c.location_signals.city_match) {
    score += 10;
  }

  if (c.property_type_signal) {
    score += 20;
  }

  if (c.source_type === 'possible_individual_listing') {
    score += 15;
  }

  if (
    c.validation_flags.includes(
      'possible_subject_duplicate'
    )
  ) {
    score -= 100;
  }

  score += (c.search_relevance || 0) * 10;

  return score;
}

candidates.sort((a, b) => priority(b) - priority(a));

// 9. SEPARATE RESULT TYPES

const individualCandidates = candidates.filter(
  c =>
    c.source_type === 'possible_individual_listing' &&
    !c.validation_flags.includes(
      'possible_subject_duplicate'
    )
);

const categoryLeads = candidates.filter(
  c => c.source_type === 'search_category_page'
);

const possibleSubjectDuplicates = candidates.filter(
  c => c.validation_flags.includes(
    'possible_subject_duplicate'
  )
);

// 10. RETURN ONE STRUCTURED ITEM

return [{
  json: {
    subject_property: subject,

    // Compatible with downstream Nebius extraction
    candidates,
    candidate_count: candidates.length,

    individual_candidates: individualCandidates,
    individual_candidate_count:
      individualCandidates.length,

    category_leads: categoryLeads,
    category_lead_count: categoryLeads.length,

    possible_subject_duplicates:
      possibleSubjectDuplicates,

    possible_subject_duplicate_count:
      possibleSubjectDuplicates.length,

    excluded_candidates: excluded,
    excluded_count: excluded.length,

    target_comparable_count: targetCount,

    matching_criteria: {
      property_type: propertyType,
      city,
      neighborhood,
      postcode,
      min_area_sqm: minArea,
      max_area_sqm: maxArea,
      subject_price_tolerance_eur: priceTolerance,
      subject_area_tolerance_sqm: areaTolerance
    },

    search_query:
      response.query || subject.search_query,

    validation_status: 'pending',
    market_confidence: 'unverified',
    benchmark_usable_for_scoring: false
  }
}];

// ============================================================
// COMBINE MARKET COMPARABLES
// Dynamic German Real Estate Investment Evaluator
//
// Supports:
// - Zero or more validated comparables
// - Optional additional Tavily candidates
// - Subject-property duplicate detection
// - Cross-listing deduplication
// - Provisional market comparison
// - Safe output for HTML report generation
//
// No hardcoded city, postcode, property type or price.
// ============================================================

// ------------------------------------------------------------
// 1. READ SUBJECT PROPERTY
// ------------------------------------------------------------

const prepared = $('CD_Prepare Market Search')
  .first().json;

const subject = prepared.market_search;

if (!subject) {
  throw new Error('Missing subject property');
}

// ------------------------------------------------------------
// 2. READ VALIDATED COMPARABLES
// ------------------------------------------------------------

const validated = $('Validate Market Comparables')
  .first().json;

// ------------------------------------------------------------
// 3. READ OPTIONAL ADDITIONAL COMPARABLES
// ------------------------------------------------------------

// The additional search may be skipped by an IF node.
// Never reference an unexecuted node's output directly.

let additional = {
  additional_candidates: []
};

if ($('Prepare Additional Comparables').isExecuted) {
  const items = $('Prepare Additional Comparables').all();

  if (items.length > 0) {
    additional = items[0].json;
  }
}

// ------------------------------------------------------------
// 4. HELPERS
// ------------------------------------------------------------

function clean(value) {
  return String(value ?? '')
    .replace(/\s+/g, ' ')
    .trim();
}

function normalize(value) {
  return clean(value)
    .toLowerCase()
    .replace(/ä/g, 'ae')
    .replace(/ö/g, 'oe')
    .replace(/ü/g, 'ue')
    .replace(/ß/g, 'ss');
}

function positiveNumber(value) {
  if (
    value === null ||
    value === undefined ||
    value === ''
  ) {
    return null;
  }

  const n = Number(value);

  return Number.isFinite(n) && n > 0
    ? n
    : null;
}

function canonicalUrl(value) {
  return clean(value)
    .toLowerCase()
    .split('#')[0]
    .split('?')[0]
    .replace(/\/+$/, '');
}

function isCategoryPage(url) {
  const u = normalize(url);

  return (
    /\/suche\/|\/search\/|\/suchen\//.test(u) ||
    /\/immobilienpreise\//.test(u) ||
    /\/s\/(?:wohnung|haus|house|apartment)\//.test(u) ||
    /\/res\/kaufen\//.test(u) ||
    /\/haus-kaufen\/?$/.test(u) ||
    /\/wohnung-kaufen\/?$/.test(u) ||
    /\/immobilienangebote\/?$/.test(u) ||
    /\/alle-immobilien\/?$/.test(u)
  );
}

function isDirectListing(url) {
  const u = canonicalUrl(url);

  if (!/^https?:\/\/[^/]+\/.+/.test(u)) {
    return false;
  }

  if (isCategoryPage(u)) {
    return false;
  }

  return (
    /immobilienscout24\.de\/expose\//.test(u) ||
    /immowelt\.de\/expose\//.test(u) ||
    /immobilien\.sparkasse\.de\/expose\//.test(u) ||
    /leverage\.immo\/immobilien\/objekt\//.test(u) ||
    /clever-immobilien\.de\/deutschland\/.+\.html/.test(u)
  );
}

function median(values) {
  if (!values.length) return null;

  const sorted = [...values].sort((a, b) => a - b);
  const mid = Math.floor(sorted.length / 2);

  return sorted.length % 2
    ? sorted[mid]
    : (sorted[mid - 1] + sorted[mid]) / 2;
}

// ------------------------------------------------------------
// 5. SUBJECT MATCHING PARAMETERS
// ------------------------------------------------------------

const subjectPrice = positiveNumber(
  subject.asking_price_eur
);

const subjectArea = positiveNumber(
  subject.living_area_sqm
);

if (!subjectPrice || !subjectArea) {
  throw new Error(
    'Subject price or living area is missing'
  );
}

const minArea = subjectArea * 0.75;
const maxArea = subjectArea * 1.25;

const subjectPriceSqm = Math.round(
  subjectPrice / subjectArea
);

const priceTolerance = Number(
  subject.subject_price_tolerance_eur ?? 1000
);

const areaTolerance = Number(
  subject.subject_area_tolerance_sqm ?? 2
);

const targetCount = Math.max(
  1,
  Math.min(
    10,
    Number(subject.target_comparable_count) || 3
  )
);

// ------------------------------------------------------------
// 6. VALIDATE AND DEDUPLICATE DIRECT CANDIDATES
// ------------------------------------------------------------

const comparables = [];
const rejectedDuringCombine = [];
const seenUrls = new Set();

const validatedCandidates = Array.isArray(
  validated.comparables
)
  ? validated.comparables
  : [];

for (const c of validatedCandidates) {

  const reasons = [];

  const url = clean(c.url);
  const price = positiveNumber(c.asking_price_eur);
  const area = positiveNumber(c.living_area_sqm);

  if (!isDirectListing(url)) {
    reasons.push('Not a recognized direct listing');
  }

  if (!price) {
    reasons.push('Missing asking price');
  }

  if (!area) {
    reasons.push('Missing living area');
  }

  if (area && (area < minArea || area > maxArea)) {
    reasons.push('Area outside preferred range');
  }

  if (
    price &&
    area &&
    Math.abs(price - subjectPrice) <= priceTolerance &&
    Math.abs(area - subjectArea) <= areaTolerance
  ) {
    reasons.push('Possible subject property duplicate');
  }

  const urlKey = canonicalUrl(url);

  if (seenUrls.has(urlKey)) {
    reasons.push('Duplicate listing URL');
  }

  // Detect likely cross-posted properties.
  // This is conservative: matching price and area
  // flags a duplicate only when location also matches.

  const duplicateProperty = comparables.some(existing => {
    const samePrice =
      Math.abs(existing.asking_price_eur - price) <= 1000;

    const sameArea =
      Math.abs(existing.living_area_sqm - area) <= 2;

    const sameLocation =
      Boolean(clean(c.location)) &&
      normalize(existing.location) ===
      normalize(c.location);

    return samePrice && sameArea && sameLocation;
  });

  if (duplicateProperty) {
    reasons.push('Possible cross-listed duplicate');
  }

  if (reasons.length) {
    rejectedDuringCombine.push({
      title: c.title || '',
      url,
      reason: reasons.join('; ')
    });

    continue;
  }

  seenUrls.add(urlKey);

  comparables.push({
    ...c,
    asking_price_eur: price,
    living_area_sqm: area,
    price_per_sqm: Math.round(price / area),
    verification_status:
      c.verification_status || 'search_snippet_only'
  });
}

// ------------------------------------------------------------
// 7. PROCESS ADDITIONAL MARKET LEADS
// ------------------------------------------------------------

const additionalCandidates = Array.isArray(
  additional.additional_candidates
)
  ? additional.additional_candidates
  : [];

const additionalLeads = [];

for (const lead of additionalCandidates) {

  const price = positiveNumber(
    lead.asking_price_eur
  );

  const area = positiveNumber(
    lead.living_area_sqm
  );

  const url = clean(lead.url);

  if (!url || !price || !area) {
    continue;
  }

  if (area < subjectArea * 0.70 ||
      area > subjectArea * 1.30) {
    continue;
  }

  // Exclude subject-property observations
  if (
    Math.abs(price - subjectPrice) <= priceTolerance &&
    Math.abs(area - subjectArea) <= areaTolerance
  ) {
    continue;
  }

  const duplicateLead = additionalLeads.some(
    existing =>
      Math.abs(
        existing.asking_price_eur - price
      ) <= 1000 &&
      Math.abs(
        existing.living_area_sqm - area
      ) <= 2
  );

  if (duplicateLead) continue;

  const possibleDuplicate = comparables.some(
    existing =>
      Math.abs(
        existing.asking_price_eur - price
      ) <= 1000 &&
      Math.abs(
        existing.living_area_sqm - area
      ) <= 2
  );

  additionalLeads.push({
    ...lead,
    asking_price_eur: price,
    living_area_sqm: area,
    price_per_sqm: Math.round(price / area),
    possible_duplicate: possibleDuplicate,
    verification_status:
      'needs_direct_listing_url'
  });
}

// ------------------------------------------------------------
// 8. SELECT UP TO TARGET COUNT
// ------------------------------------------------------------

const selected = comparables.slice(0, targetCount);

// Only calculate an indicative median with
// at least 3 eligible direct-listing candidates.

const provisionalMedian =
  selected.length >= 3
    ? median(
        selected.map(c => c.price_per_sqm)
      )
    : null;

const differencePct =
  provisionalMedian !== null
    ? Math.round(
        (
          (subjectPriceSqm - provisionalMedian) /
          provisionalMedian
        ) * 1000
      ) / 10
    : null;

// ------------------------------------------------------------
// 9. MARKET ANALYSIS STATUS
// ------------------------------------------------------------

let status;

if (selected.length === 0) {
  status = 'Insufficient comparable evidence';
} else if (selected.length < 3) {
  status = 'Fewer than 3 comparable candidates';
} else {
  status = 'Preliminary asking-price comparison only';
}

// ------------------------------------------------------------
// 10. RETURN ONE OUTPUT ITEM
// ------------------------------------------------------------

return [{
  json: {
    subject_property: subject,
    benchmark: selected.length < 3 ? (validated.benchmark || null) : null,

    comparables: selected,
    comparable_count: selected.length,

    additional_leads: additionalLeads,
    lead_count: additionalLeads.length,

    rejected_candidates:
      validated.rejected_candidates || [],

    rejected_during_combine:
      rejectedDuringCombine,

    rejected_count:
      (validated.rejected_candidates || []).length +
      rejectedDuringCombine.length,

    provisional_market_median_per_sqm:
      provisionalMedian,

    provisional_snippet_median_per_sqm:
      provisionalMedian,

    subject_price_per_sqm:
      subjectPriceSqm,

    provisional_price_difference_pct:
      differencePct,

    market_median_per_sqm: null,

    market_confidence: 'unverified',

    benchmark_usable_for_scoring: false,

    market_analysis_status: status,

    market_search_date:
      subject.search_date || null,

    target_comparable_count: targetCount
  }
}];

// ======================================================
// PREPARE CHAT HANDOFF
// German Property Investment Evaluator
// ======================================================

// 1. Read the saved database row
const saved = $('Save Final Report').first().json;

// 2. Read the original property context
const prepared = $('Prepare Property Context').first().json;

// 3. Read the final assembled report
const report = $('Assemble Final Investment Report')
  .first().json;

// 4. Resolve property identity
const propertyId = String(
  saved.property_id ||
  prepared.property_id ||
  ''
).trim();

if (!propertyId) {
  throw new Error('Missing property_id for chat handoff');
}

// 5. Validate the saved HTML
const reportHtml = String(
  saved.final_report_html ||
  report.final_investment_report_html ||
  ''
).trim();

if (!reportHtml) {
  throw new Error('Final investment report HTML is missing');
}

// 6. Return handoff metadata
return [{
  json: {
    property_id: propertyId,

    database_row_id:
      saved.id ?? null,

    report_status: 'completed',

    report_ready: true,

    chat_available: true,

    property_title:
      report.property_title ||
      prepared.property_title ||
      'Property Investment Report',

    source_filename:
      saved.source_filename ||
      prepared.source_filename ||
      '',

    report_json: (() => {
      const value = saved.report_json;

      if (value == null || value === '') {
      return null;
    }

    return typeof value === 'string'
      ? JSON.parse(value)
      : value;
    })(),

    market_summary: report.market_summary || null,

    report_html:
      report.final_investment_report_html ?? null,

    handoff_ready: true
  }
}];
